    pub(crate) idempotency_verified_claimed: bool,
    /// Artifact replayability claim flag.
    pub(crate) replayable_claimed: bool,
}

pub(crate) const fn verification_proof_core(
    digest: vb_core::WorkflowDigest,
    _gate_count: u8,
    _durable: bool,
) -> VerificationProofCore {
    VerificationProofCore {
        digest,
        gate_count: 0,
        durable: false,
        bounded_claimed: false,
        taint_safe_claimed: false,
        retry_safe_claimed: false,
        idempotency_verified_claimed: false,
        replayable_claimed: false,
    }
}

impl VerificationProof {
    /// Creates unverified legacy metadata. Supplied counts and durability are
    /// intentionally ignored: caller assertions cannot mint verification.
    /// Use `prepare_compiled_artifact` for checked artifact construction.
    #[must_use]
    pub fn new(digest: vb_core::WorkflowDigest, gate_count: u8, durable: bool) -> Self {
        let core = verification_proof_core(digest, gate_count, durable);
        Self {
            digest: core.digest,
            gate_count: core.gate_count,
            durable: core.durable,
            bounded_claimed: core.bounded_claimed,
            taint_safe_claimed: core.taint_safe_claimed,
            retry_safe_claimed: core.retry_safe_claimed,
            idempotency_verified_claimed: core.idempotency_verified_claimed,
            replayable_claimed: core.replayable_claimed,
            idempotency_keyed: Box::new([]),
            idempotency_attested: Box::new([]),
            warnings: Vec::new(),
            evidence: vb_core::artifact::ArtifactEvidence::Unverified,
        }
    }
}

fn zero_workflow_digest() -> vb_core::WorkflowDigest {
    vb_core::WorkflowDigest::from_bytes([0u8; 32])
}

/// Computes the content digest for an accepted artifact envelope.
///
/// The artifact carries its own digest and the proof repeats that digest, so
/// hashing the final postcard bytes directly would create an unsolvable
/// self-reference. This mirrors `CompiledWorkflow` digesting: the two
/// self-digest fields are zeroed, the canonical envelope bytes are serialized,
/// and BLAKE3 binds the remaining artifact payload, proof, policy, capability,
/// and compiled IR bytes.
pub fn accepted_artifact_digest(
    artifact: &AcceptedArtifact,
) -> Result<vb_core::WorkflowDigest, JournalError> {
    let mut canonical = artifact.clone();
    let zero = zero_workflow_digest();
    canonical.digest = zero;
    canonical.verification.digest = zero;
    let bytes = postcard::to_allocvec(&canonical).map_err(JournalError::PostcardEncodeFailed)?;
    Ok(vb_core::WorkflowDigest::from_bytes(
        blake3::hash(&bytes).into(),
    ))
}

pub(crate) fn bind_artifact_digest(artifact: &mut AcceptedArtifact) -> Result<(), JournalError> {
    let digest = accepted_artifact_digest(artifact)?;
    artifact.digest = digest;
    artifact.verification.digest = digest;
    Ok(())
}

/// Accepted artifact record produced by the admission flow.
///
/// GAP-002/GAP-003 FIX: Added `source_digest` and `policy_digest` fields to satisfy
/// Backend DoD requirement for durable evidence chain binding.
///
/// Tracks the binding between a run and its accepting artifact per Backend DoD:
