    let a = VerificationWarning {
        code: 1,
        message: Box::from("alpha"),
        gate: 2,
    };
    let b = VerificationWarning {
        code: 99,
        message: Box::from("alpha"),
        gate: 2,
    };
    assert_ne!(a, b);
}

