    /// fail-closed behavior must invoke this method and handle the result.
    ///
    /// # Errors
    ///
    /// Returns `JournalError` if the underlying storage fails to persist.
    pub fn close(&mut self) -> Result<(), JournalError> {
        self.persist_strict()
